import itertools
from fractions import Fraction as F
S=[]
for seq in itertools.product('GD',repeat=3):
    o=''
    for ch in seq:
        o+=ch
        if ch=='D': break
    if o not in S: S.append(o)
print(len(S), [o for o in S if 'D' in o], {o:F(1,2**len(o)) for o in S})  # 4, 3 outcomes, unequal probs
